content:
/* ==========================================================================
   リアルタイム3D太陽系シミュレーター - 宇宙空間デザインシステム
   ========================================================================== */

:root {
  --bg-deep-space: #030712;
  --bg-glass-panel: rgba(13, 22, 44, 0.72);
  --bg-glass-card: rgba(15, 23, 42, 0.88);
  --bg-glass-hover: rgba(30, 48, 80, 0.85);

  --border-neon-subtle: rgba(56, 189, 248, 0.25);
  --border-neon-active: rgba(56, 189, 248, 0.8);
  --border-glass: rgba(255, 255, 255, 0.12);

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-accent: #38bdf8;
  --text-glow: #e0f2fe;

  --accent-cyan: #06b6d4;
  --accent-blue: #3b82f6;
  --accent-glow: rgba(56, 189, 248, 0.35);

  --font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', monospace;

  --transition-fast: 0.18s ease;
  --transition-normal: 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --z-canvas: 1;
  --z-hud: 10;
  --z-modal-backdrop: 50;
  --z-modal: 60;
}

/* リセット & ベース */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  background-color: var(--bg-deep-space);
  color: var(--text-primary);
  font-family: var(--font-family);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  user-select: none;
}

#root {
  width: 100%;
  height: 100vh;
  height: 100dvh;
}

/* アプリ全体レイアウト */
.solar-app {
  position: relative;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  background: radial-gradient(ellipse at center, #0a1128 0%, #030712 100%);
}

/* Three.js 描画キャンバスコンテナ */
.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: var(--z-canvas);
  cursor: grab;
  outline: none;
}

.canvas-container:active {
  cursor: grabbing;
}

.canvas-container canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
}

/* HUD オーバーレイ */
.hud-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: var(--z-hud);
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 1rem;
}

/* 上部ヘッダー */
.top-header {
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.25rem;
  background: var(--bg-glass-panel);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-glass);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), inset 0 0 12px rgba(56, 189, 248, 0.05);
  max-width: fit-content;
}

.app-title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  text-shadow: 0 0 12px rgba(56, 189, 248, 0.6);
}

.app-subtitle {
  font-size: 0.78rem;
  color: var(--text-secondary);
  letter-spacing: 0.03em;
  font-weight: 400;
}

/* 惑星クイックセレクターバー（画面上部中央〜下部上） */
.planet-selector-bar {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  background: var(--bg-glass-panel);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border-glass);
  border-radius: var(--radius-full);
  overflow-x: auto;
  max-width: 100%;
  align-self: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  scrollbar-width: none;
}

.planet-selector-bar::-webkit-scrollbar {
  display: none;
}

/* 惑星ボタン */
.planet-btn {
  pointer-events: auto;
  appearance: none;
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-secondary);
  border: 1px solid transparent;
  border-radius: var(--radius-full);
  padding: 0.4rem 0.85rem;
  font-size: 0.82rem;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.planet-btn:hover {
  background: var(--bg-glass-hover);
  color: var(--text-primary);
  border-color: var(--border-neon-subtle);
  transform: translateY(-1px);
}

.planet-btn:active {
  transform: translateY(0);
}

.planet-btn-active {
  background: rgba(56, 189, 248, 0.18);
  color: var(--text-glow);
  border-color: var(--border-neon-active);
  box-shadow: 0 0 12px var(--accent-glow);
  font-weight: 600;
}

/* コントロールパネル（下部操作群） */
.controls-panel {
  pointer-events: auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  padding: 0.75rem 1.25rem;
  background: var(--bg-glass-panel);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid var(--border-glass);
  border-radius: var(--radius-lg);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45);
  align-self: center;
  max-width: 95vw;
}

/* 操作ボタンスタイル */
.control-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border-glass);
  color: var(--text-primary);
  padding: 0.5rem 1rem;
  border-radius: var(--radius-md);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 38px;
  transition: all var(--transition-fast);
}

.control-btn:hover {
  background: rgba(56, 189, 248, 0.2);
  border-color: var(--border-neon-subtle);
  box-shadow: 0 0 10px var(--accent-glow);
}

.control-btn:active {
  transform: scale(0.97);
}

/* カメラリセットボタン */
.camera-reset-btn {
  background: rgba(14, 165, 233, 0.15);
  border: 1px solid rgba(56, 189, 248, 0.4);
  color: #bae6fd;
}

.camera-reset-btn:hover {
  background: rgba(14, 165, 233, 0.3);
  border-color: var(--accent-cyan);
}

/* キーボード操作時のフォーカスインジケータ */
.planet-btn:focus-visible,
.control-btn:focus-visible,
.close-btn:focus-visible {
  outline: 2px solid var(--accent-cyan);
  outline-offset: 2px;
}

.speed-slider:focus-visible,
.toggle-switch input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--accent-cyan);
  outline-offset: 3px;
}

/* 速度スライダーグループ */
.speed-slider-group {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0 0.5rem;
  min-width: 170px;
}

.speed-label {
  font-size: 0.8rem;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  white-space: nowrap;
}

.speed-slider {
  appearance: none;
  -webkit-appearance: none;
  width: 100px;
  height: 6px;
  background: rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-full);
  outline: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.speed-slider:hover {
  background: rgba(255, 255, 255, 0.25);
}

.speed-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--text-accent);
  box-shadow: 0 0 8px var(--accent-cyan);
  cursor: pointer;
  transition: transform var(--transition-fast);
}

.speed-slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.speed-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--text-accent);
  box-shadow: 0 0 8px var(--accent-cyan);
  border: none;
  cursor: pointer;
}

/* トグルスイッチ（軌道線等） */
.toggle-switch {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.82rem;
  color: var(--text-secondary);
  cursor: pointer;
}

.toggle-switch input[type="checkbox"] {
  width: 16px;
  height: 16px;
  accent-color: var(--accent-cyan);
  cursor: pointer;
}

/* 惑星情報カードモーダル */
.info-modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  z-index: var(--z-modal);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  pointer-events: auto;
}

.info-modal-backdrop {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(3, 7, 18, 0.65);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: -1;
  animation: fadeIn 0.2s ease-out;
}

.info-card {
  width: 100%;
  max-width: 520px;
  background: var(--bg-glass-card);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--border-neon-subtle);
  border-radius: var(--radius-lg);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.6), 0 0 24px rgba(56, 189, 248, 0.15);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  animation: scaleIn 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.info-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border-glass);
  background: linear-gradient(to right, rgba(56, 189, 248, 0.08), transparent);
}

.info-title {
  font-size: 1.45rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: baseline;
  gap: 0.6rem;
}

.info-subtitle {
  font-size: 0.85rem;
  color: var(--accent-cyan);
  font-weight: 400;
  font-family: var(--font-mono);
}

.close-btn {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-glass);
  color: var(--text-secondary);
  border-radius: var(--radius-full);
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 1.1rem;
  transition: all var(--transition-fast);
}

.close-btn:hover {
  background: rgba(239, 68, 68, 0.25);
  color: #fca5a5;
  border-color: rgba(239, 68, 68, 0.5);
}

.info-body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  max-height: 70vh;
  overflow-y: auto;
}

.info-spec-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

.spec-item {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: var(--radius-md);
  padding: 0.75rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.spec-label {
  font-size: 0.72rem;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.spec-value {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-glow);
  font-family: var(--font-mono);
}

.info-desc {
  font-size: 0.9rem;
  line-height: 1.65;
  color: #cbd5e1;
  background: rgba(0, 0, 0, 0.2);
  padding: 1rem;
  border-radius: var(--radius-md);
  border-left: 3px solid var(--accent-cyan);
}

/* アニメーション */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.93) translateY(10px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

/* レスポンシブ対応 (モバイル・小型端末) */
@media (max-width: 640px) {
  .hud-overlay {
    padding: 0.5rem;
    gap: 0.5rem;
  }

  .top-header {
    padding: 0.5rem 0.85rem;
  }

  .app-title {
    font-size: 1.05rem;
  }

  .app-subtitle {
    font-size: 0.7rem;
  }

  .planet-selector-bar {
    width: 100%;
    padding: 0.4rem;
    gap: 0.35rem;
  }

  .planet-btn {
    padding: 0.35rem 0.65rem;
    font-size: 0.75rem;
  }

  .controls-panel {
    width: 100%;
    padding: 0.6rem;
    gap: 0.6rem;
    border-radius: var(--radius-md);
  }

  .control-btn {
    padding: 0.4rem 0.75rem;
    font-size: 0.78rem;
    min-height: 34px;
  }

  .speed-slider-group {
    min-width: 140px;
    gap: 0.4rem;
  }

  .speed-slider {
    width: 70px;
  }

  .info-spec-grid {
    grid-template-columns: 1fr;
    gap: 0.5rem;
  }

  .info-card {
    max-width: 100%;
    border-radius: var(--radius-md);
  }

  .info-header {
    padding: 1rem;
  }

  .info-body {
    padding: 1rem;
    gap: 1rem;
  }
}

export type CelestialBodyType = 'star' | 'terrestrial' | 'gas_giant' | 'ice_giant';

export interface PlanetData {
  id: string;
  name: string;
  englishName: string;
  type: CelestialBodyType;
  radius: number;
  distance: number;
  distanceAU?: string;
  orbitSpeed: number;
  rotationSpeed: number;
  axialTilt: number; // 自転軸傾斜角 (度)
  gravity?: string; // 表面重力 (m/s² または G)
  color: string;
  emissiveColor?: string;
  rings?: {
    innerRadius: number;
    outerRadius: number;
    color: string;
  };
  overview: string;
  diameterKm: string;
  orbitPeriodDays: string;
  surfaceTemp: string;
  moonsCount: number;
  notableMoons?: string[];
}

export interface SimulationSettings {
  speedMultiplier: number;
  isPaused: boolean;
  showOrbits: boolean;
  focusedPlanetId: string | null;
  cameraMode?: 'overview' | 'follow';
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { PlanetData, SimulationSettings } from '../types';
import { SUN_DATA, PLANETS_DATA } from '../solarData';

interface SolarSystemCanvasProps {
  settings: SimulationSettings;
  onSelectPlanet: (id: string | null) => void;
}

interface PlanetMeshInfo {
  id: string;
  data: PlanetData;
  pivot: THREE.Group;
  tiltGroup: THREE.Group;
  mesh: THREE.Mesh;
  currentOrbitAngle: number;
  orbitDistance: number;
  orbitSpeed: number;
  rotationSpeed: number;
  ringMesh?: THREE.Mesh;
}

// 惑星の自転軸の傾斜（ラジアン）
const PLANET_TILTS: Record<string, number> = {
  mercury: THREE.MathUtils.degToRad(0.034),
  venus: THREE.MathUtils.degToRad(177.3),
  earth: THREE.MathUtils.degToRad(23.44),
  mars: THREE.MathUtils.degToRad(25.19),
  jupiter: THREE.MathUtils.degToRad(3.13),
  saturn: THREE.MathUtils.degToRad(26.73),
  uranus: THREE.MathUtils.degToRad(97.77),
  neptune: THREE.MathUtils.degToRad(28.32),
};

const DEFAULT_CAMERA_ANGLES = {
  theta: Math.PI / 4,
  phi: Math.PI / 3,
  radius: 140,
};

const SolarSystemCanvas = ({
  settings,
  onSelectPlanet,
}: SolarSystemCanvasProps) => {
  const containerRef = useRef<HTMLDivElement | null>(null);

  // Three.js インスタンス保持用のRef
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const planetMeshesRef = useRef<PlanetMeshInfo[]>([]);
  const sunMeshRef = useRef<THREE.Mesh | null>(null);
  const coronaMeshRef = useRef<THREE.Mesh | null>(null);
  const orbitLinesRef = useRef<THREE.Line[]>([]);

  // 操作とカメラ遷移制御
  const isDraggingRef = useRef<boolean>(false);
  const previousPointerPositionRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const cameraAnglesRef = useRef<{ theta: number; phi: number; radius: number }>({
    ...DEFAULT_CAMERA_ANGLES,
  });
  const cameraTargetRef = useRef<THREE.Vector3>(new THREE.Vector3(0, 0, 0));
  const pointerDownPosRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });

  // タッチ操作管理 (ピンチズーム対応)
  const activeTouchesRef = useRef<Map<number, { x: number; y: number }>>(new Map());
  const initialPinchDistanceRef = useRef<number | null>(null);
  const initialRadiusRef = useRef<number>(140);

  // settingsの最新状態をアニメーションループ内で参照
  const settingsRef = useRef<SimulationSettings>(settings);
  useEffect(() => {
    settingsRef.current = settings;
    // 軌道線表示切替
    orbitLinesRef.current.forEach((line) => {
      line.visible = settings.showOrbits;
    });
  }, [settings]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const width = container.clientWidth;
    const height = container.clientHeight;

    // 1. シーン初期化
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    // 2. カメラ初期化
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 2000);
    cameraRef.current = camera;

    // 3. レンダラー初期化
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: 'high-performance',
    });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    container.innerHTML = '';
    container.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // 4. 背景の星屑パーティクル
    const starsCount = 2000;
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = new Float32Array(starsCount * 3);
    const starColors = new Float32Array(starsCount * 3);

    for (let i = 0; i < starsCount; i++) {
      const radius = THREE.MathUtils.randFloat(300, 900);
      const theta = THREE.MathUtils.randFloat(0, Math.PI * 2);
      const phi = THREE.MathUtils.randFloat(0, Math.PI);

      starPositions[i * 3] = radius * Math.sin(phi) * Math.cos(theta);
      starPositions[i * 3 + 1] = radius * Math.cos(phi);
      starPositions[i * 3 + 2] = radius * Math.sin(phi) * Math.sin(theta);

      const tint = THREE.MathUtils.randFloat(0.7, 1.0);
      starColors[i * 3] = tint;
      starColors[i * 3 + 1] = tint * 0.95;
      starColors[i * 3 + 2] = tint * 1.1;
    }

    starGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
    starGeometry.setAttribute('color', new THREE.BufferAttribute(starColors, 3));

    const starMaterial = new THREE.PointsMaterial({
      size: 1.5,
      vertexColors: true,
      transparent: true,
      opacity: 0.85,
    });
    const starField = new THREE.Points(starGeometry, starMaterial);
    scene.add(starField);

    // 5. 環境光と光源（太陽光）
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.22);
    scene.add(ambientLight);

    const sunLight = new THREE.PointLight(0xfff7ed, 3.2, 500, 0.5);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);

    // 6. 太陽の生成
    const sunGeom = new THREE.SphereGeometry(SUN_DATA.radius, 32, 32);
    const sunMat = new THREE.MeshBasicMaterial({
      color: SUN_DATA.color,
    });
    const sunMesh = new THREE.Mesh(sunGeom, sunMat);
    sunMesh.userData = { id: SUN_DATA.id };
    scene.add(sunMesh);
    sunMeshRef.current = sunMesh;

    // 太陽の光冠グローメッシュ
    const coronaGeom = new THREE.SphereGeometry(SUN_DATA.radius * 1.25, 32, 32);
    const coronaMat = new THREE.MeshBasicMaterial({
      color: 0xff6600,
      transparent: true,
      opacity: 0.25,
      side: THREE.BackSide,
    });
    const coronaMesh = new THREE.Mesh(coronaGeom, coronaMat);
    sunMesh.add(coronaMesh);
    coronaMeshRef.current = coronaMesh;

    // 7. 惑星および軌道線の生成
    const planetsList: PlanetMeshInfo[] = [];
    const orbitLinesList: THREE.Line[] = [];

    PLANETS_DATA.forEach((pData, index) => {
      // 軌道グループピボット
      const orbitPivot = new THREE.Group();
      scene.add(orbitPivot);

      // 自転軸傾斜（tilt）用のラッパーグループ
      const tiltGroup = new THREE.Group();
      const tiltAngle = PLANET_TILTS[pData.id] || 0;
      tiltGroup.rotation.z = tiltAngle;

      // 惑星本体
      const pGeom = new THREE.SphereGeometry(pData.radius, 32, 32);
      const pMat = new THREE.MeshStandardMaterial({
        color: pData.color,
        roughness: 0.6,
        metalness: 0.2,
      });
      const pMesh = new THREE.Mesh(pGeom, pMat);
      pMesh.userData = { id: pData.id };
      tiltGroup.add(pMesh);

      // 土星などの環（リング）
      let ringMesh: THREE.Mesh | undefined;
      if (pData.rings) {
        const ringGeom = new THREE.RingGeometry(pData.rings.innerRadius, pData.rings.outerRadius, 64);
        const ringMat = new THREE.MeshStandardMaterial({
          color: pData.rings.color,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.8,
          roughness: 0.5,
        });
        ringMesh = new THREE.Mesh(ringGeom, ringMat);
        ringMesh.rotation.x = Math.PI / 2; // 赤道面に水平に配置（tiltGroupで一緒に傾く）
        tiltGroup.add(ringMesh);
      }

      // 初期の公転位置を散らして自然に見せる
      const initialAngle = (index / PLANETS_DATA.length) * Math.PI * 2;
      tiltGroup.position.set(
        Math.cos(initialAngle) * pData.distance,
        0,
        Math.sin(initialAngle) * pData.distance
      );
      orbitPivot.add(tiltGroup);

      // 軌道線（輪郭）
      const curve = new THREE.EllipseCurve(
        0, 0,
        pData.distance, pData.distance,
        0, 2 * Math.PI,
        false,
        0
      );
      const points = curve.getPoints(128);
      const orbitLineGeom = new THREE.BufferGeometry().setFromPoints(
        points.map((pt) => new THREE.Vector3(pt.x, 0, pt.y))
      );
      const orbitLineMat = new THREE.LineBasicMaterial({
        color: 0x38bdf8,
        transparent: true,
        opacity: 0.3,
      });
      const orbitLine = new THREE.Line(orbitLineGeom, orbitLineMat);
      orbitLine.visible = settingsRef.current.showOrbits;
      scene.add(orbitLine);
      orbitLinesList.push(orbitLine);

      planetsList.push({
        id: pData.id,
        data: pData,
        pivot: orbitPivot,
        tiltGroup,
        mesh: pMesh,
        currentOrbitAngle: initialAngle,
        orbitDistance: pData.distance,
        orbitSpeed: pData.orbitSpeed,
        rotationSpeed: pData.rotationSpeed,
        ringMesh,
      });
    });

    planetMeshesRef.current = planetsList;
    orbitLinesRef.current = orbitLinesList;

    // 8. レンダリングループ
    let animationFrameId: number;
    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      const currentSettings = settingsRef.current;
      const speed = currentSettings.isPaused ? 0 : currentSettings.speedMultiplier;

      // 太陽自転
      if (sunMeshRef.current) {
        sunMeshRef.current.rotation.y += SUN_DATA.rotationSpeed * speed;
      }

      // 惑星公転・自転
      planetMeshesRef.current.forEach((item) => {
        item.currentOrbitAngle += item.orbitSpeed * 0.4 * speed;
        item.tiltGroup.position.x = Math.cos(item.currentOrbitAngle) * item.orbitDistance;
        item.tiltGroup.position.z = Math.sin(item.currentOrbitAngle) * item.orbitDistance;
        // 自転軸に沿った回転
        item.mesh.rotation.y += item.rotationSpeed * speed;
      });

      // カメラ追従処理
      const focusedId = currentSettings.focusedPlanetId;
      let targetPos = new THREE.Vector3(0, 0, 0);
      let targetCameraDistance = DEFAULT_CAMERA_ANGLES.radius;

      if (focusedId) {
        if (focusedId === 'sun') {
          targetPos = new THREE.Vector3(0, 0, 0);
          targetCameraDistance = 30;
        } else {
          const focusedPlanet = planetMeshesRef.current.find((p) => p.id === focusedId);
          if (focusedPlanet) {
            targetPos.copy(focusedPlanet.tiltGroup.position);
            targetCameraDistance = Math.max(focusedPlanet.data.radius * 7, 10);
          }
        }
      } else {
        // 未選択時は全体俯瞰角度へスムーズにリセット誘導
        cameraAnglesRef.current.theta = THREE.MathUtils.lerp(
          cameraAnglesRef.current.theta,
          DEFAULT_CAMERA_ANGLES.theta,
          0.04
        );
        cameraAnglesRef.current.phi = THREE.MathUtils.lerp(
          cameraAnglesRef.current.phi,
          DEFAULT_CAMERA_ANGLES.phi,
          0.04
        );
      }

      // 目標座標へカメラターゲットを滑らかに移動 (lerp)
      cameraTargetRef.current.lerp(targetPos, 0.05);

      // 距離を滑らかに補正
      cameraAnglesRef.current.radius = THREE.MathUtils.lerp(
        cameraAnglesRef.current.radius,
        targetCameraDistance,
        0.05
      );

      // 球面座標からカメラ位置を計算
      const { theta, phi, radius } = cameraAnglesRef.current;
      const camX = cameraTargetRef.current.x + radius * Math.sin(phi) * Math.sin(theta);
      const camY = cameraTargetRef.current.y + radius * Math.cos(phi);
      const camZ = cameraTargetRef.current.z + radius * Math.sin(phi) * Math.cos(theta);

      camera.position.set(camX, camY, camZ);
      camera.lookAt(cameraTargetRef.current);

      renderer.render(scene, camera);
    };

    animate();

    // 9. ポインター／ドラッグ操作イベント
    const handlePointerDown = (e: PointerEvent) => {
      activeTouchesRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (activeTouchesRef.current.size === 1) {
        isDraggingRef.current = true;
        previousPointerPositionRef.current = { x: e.clientX, y: e.clientY };
        pointerDownPosRef.current = { x: e.clientX, y: e.clientY };
      } else if (activeTouchesRef.current.size === 2) {
        // 2点タッチピンチ開始
        isDraggingRef.current = false;
        const points = Array.from(activeTouchesRef.current.values());
        initialPinchDistanceRef.current = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );
        initialRadiusRef.current = cameraAnglesRef.current.radius;
      }
    };

    const handlePointerMove = (e: PointerEvent) => {
      if (activeTouchesRef.current.has(e.pointerId)) {
        activeTouchesRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
      }

      // 2点タッチピンチズーム処理
      if (activeTouchesRef.current.size === 2 && initialPinchDistanceRef.current !== null) {
        const points = Array.from(activeTouchesRef.current.values());
        const currentDistance = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );
        if (currentDistance > 0) {
          const ratio = initialPinchDistanceRef.current / currentDistance;
          cameraAnglesRef.current.radius = Math.max(8, Math.min(600, initialRadiusRef.current * ratio));
        }
        return;
      }

      // 1点ドラッグによる回転
      if (!isDraggingRef.current) return;

      const deltaX = e.clientX - previousPointerPositionRef.current.x;
      const deltaY = e.clientY - previousPointerPositionRef.current.y;

      cameraAnglesRef.current.theta -= deltaX * 0.006;
      cameraAnglesRef.current.phi -= deltaY * 0.006;

      // 垂直角度の制限（真上・真下でのフリップ防止）
      cameraAnglesRef.current.phi = Math.max(0.1, Math.min(Math.PI - 0.1, cameraAnglesRef.current.phi));

      previousPointerPositionRef.current = { x: e.clientX, y: e.clientY };
    };

    const handlePointerUp = (e: PointerEvent) => {
      activeTouchesRef.current.delete(e.pointerId);

      if (activeTouchesRef.current.size < 2) {
        initialPinchDistanceRef.current = null;
      }

      if (activeTouchesRef.current.size === 1) {
        const remainingPoint = Array.from(activeTouchesRef.current.values())[0];
        previousPointerPositionRef.current = { x: remainingPoint.x, y: remainingPoint.y };
        isDraggingRef.current = true;
      } else {
        isDraggingRef.current = false;
      }

      // クリック判定（移動量が小さい場合のみ選択）
      const dx = Math.abs(e.clientX - pointerDownPosRef.current.x);
      const dy = Math.abs(e.clientY - pointerDownPosRef.current.y);
      if (dx < 6 && dy < 6 && activeTouchesRef.current.size === 0) {
        const rect = renderer.domElement.getBoundingClientRect();
        pointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
        pointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

        raycaster.setFromCamera(pointer, camera);
        const clickableMeshes: THREE.Object3D[] = [];
        if (sunMeshRef.current) clickableMeshes.push(sunMeshRef.current);
        planetMeshesRef.current.forEach((p) => clickableMeshes.push(p.mesh));

        const intersects = raycaster.intersectObjects(clickableMeshes, false);
        if (intersects.length > 0) {
          const hitMesh = intersects[0].object;
          const hitId = hitMesh.userData?.id;
          if (hitId) {
            onSelectPlanet(hitId);
          }
        }
      }
    };

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      const zoomFactor = e.deltaY > 0 ? 1.1 : 0.9;
      cameraAnglesRef.current.radius = Math.max(8, Math.min(600, cameraAnglesRef.current.radius * zoomFactor));
    };

    const handleResize = () => {
      if (!container || !renderer || !camera) return;
      const w = container.clientWidth;
      const h = container.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };

    window.addEventListener('resize', handleResize);
    const canvasEl = renderer.domElement;
    canvasEl.addEventListener('pointerdown', handlePointerDown);
    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);
    canvasEl.addEventListener('wheel', handleWheel, { passive: false });

    // クリーンアップ
    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
      canvasEl.removeEventListener('pointerdown', handlePointerDown);
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
      canvasEl.removeEventListener('wheel', handleWheel);

      // 太陽リソース破棄
      if (sunMeshRef.current) {
        sunMeshRef.current.geometry.dispose();
        if (Array.isArray(sunMeshRef.current.material)) {
          sunMeshRef.current.material.forEach((m) => m.dispose());
        } else {
          sunMeshRef.current.material.dispose();
        }
      }
      if (coronaMeshRef.current) {
        coronaMeshRef.current.geometry.dispose();
        if (Array.isArray(coronaMeshRef.current.material)) {
          coronaMeshRef.current.material.forEach((m) => m.dispose());
        } else {
          coronaMeshRef.current.material.dispose();
        }
      }

      // 各惑星メッシュおよびリングリソース破棄
      planetsList.forEach((p) => {
        p.mesh.geometry.dispose();
        if (Array.isArray(p.mesh.material)) {
          p.mesh.material.forEach((m) => m.dispose());
        } else {
          p.mesh.material.dispose();
        }

        if (p.ringMesh) {
          p.ringMesh.geometry.dispose();
          if (Array.isArray(p.ringMesh.material)) {
            p.ringMesh.material.forEach((m) => m.dispose());
          } else {
            p.ringMesh.material.dispose();
          }
        }
      });

      // 軌道線リソース破棄
      orbitLinesList.forEach((line) => {
        line.geometry.dispose();
        if (Array.isArray(line.material)) {
          line.material.forEach((m) => m.dispose());
        } else {
          line.material.dispose();
        }
      });

      // 背景星屑破棄
      starGeometry.dispose();
      starMaterial.dispose();

      scene.clear();
      renderer.dispose();
    };
  }, [onSelectPlanet]);

  return <div ref={containerRef} className="canvas-container" />;
};

export default SolarSystemCanvas;

import { ChangeEvent } from 'react';
import { SimulationSettings } from '../types';
import { SUN_DATA, PLANETS_DATA } from '../solarData';

interface ControlsBarProps {
  settings: SimulationSettings;
  onUpdateSettings: (updater: (prev: SimulationSettings) => SimulationSettings) => void;
  onSelectPlanet: (id: string | null) => void;
  onOpenModal: () => void;
}

const ControlsBar = ({
  settings,
  onUpdateSettings,
  onSelectPlanet,
  onOpenModal,
}: ControlsBarProps) => {
  const allCelestialBodies = [SUN_DATA, ...PLANETS_DATA];

  const handleTogglePause = () => {
    onUpdateSettings((prev) => ({
      ...prev,
      isPaused: !prev.isPaused,
    }));
  };

  const handleSpeedChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    onUpdateSettings((prev) => ({
      ...prev,
      speedMultiplier: isNaN(val) ? 1.0 : val,
    }));
  };

  // 速度を1.0x（等倍）にリセット
  const handleResetSpeed = () => {
    onUpdateSettings((prev) => ({
      ...prev,
      speedMultiplier: 1.0,
    }));
  };

  const handleToggleOrbits = (e: ChangeEvent<HTMLInputElement>) => {
    const checked = e.target.checked;
    onUpdateSettings((prev) => ({
      ...prev,
      showOrbits: checked,
    }));
  };

  // 全体俯瞰へリセット（追従解除＆カメラ位置リセット誘導）
  const handleResetCamera = () => {
    onSelectPlanet(null);
  };

  const selectedBody = allCelestialBodies.find((b) => b.id === settings.focusedPlanetId);

  return (
    <>
      {/* 惑星クイックセレクターバー */}
      <div className="planet-selector-bar">
        {allCelestialBodies.map((body) => {
          const isActive = settings.focusedPlanetId === body.id;
          return (
            <button
              key={body.id}
              type="button"
              className={isActive ? 'planet-btn planet-btn-active' : 'planet-btn'}
              onClick={() => onSelectPlanet(body.id)}
            >
              <span>{body.name}</span>
            </button>
          );
        })}
      </div>

      {/* 下部操作パネル */}
      <div className="controls-panel">
        {/* 再生/一時停止 */}
        <button
          type="button"
          className="control-btn"
          onClick={handleTogglePause}
        >
          {settings.isPaused ? '▶ 再生' : '⏸ 一時停止'}
        </button>

        {/* 公転速度スライダー */}
        <div className="speed-slider-group">
          <span
            className="speed-label"
            title="クリックで等倍(1.0x)に戻す"
            onClick={handleResetSpeed}
            style={{ cursor: 'pointer' }}
          >
            速度: {settings.speedMultiplier.toFixed(1)}x
          </span>
          <input
            type="range"
            min="0.1"
            max="5.0"
            step="0.1"
            aria-label="シミュレーション速度"
            value={settings.speedMultiplier}
            onChange={handleSpeedChange}
            onDoubleClick={handleResetSpeed}
            className="speed-slider"
          />
        </div>

        {/* 軌道線トグルスイッチ */}
        <label className="toggle-switch">
          <input
            type="checkbox"
            checked={settings.showOrbits}
            onChange={handleToggleOrbits}
          />
          <span>軌道線</span>
        </label>

        {/* 解説カードを開くボタン（選択中天体または太陽系全体） */}
        <button
          type="button"
          className="control-btn"
          onClick={() => {
            if (!selectedBody) {
              // 選択がない場合は太陽系中心（太陽）を選択してからモーダルを開く
              onSelectPlanet(SUN_DATA.id);
            }
            onOpenModal();
          }}
        >
          {selectedBody ? `ℹ️ ${selectedBody.name}の解説` : 'ℹ️ 太陽系の解説'}
        </button>

        {/* カメラリセットボタン */}
        <button
          type="button"
          className="control-btn camera-reset-btn"
          onClick={handleResetCamera}
        >
          🌌 全体俯瞰
        </button>
      </div>
    </>
  );
};

export default ControlsBar;

import { useEffect, useRef } from 'react';
import { PlanetData } from '../types';

interface PlanetInfoModalProps {
  planet: PlanetData | null;
  isOpen: boolean;
  onClose: () => void;
}

const PlanetInfoModal = ({
  planet,
  isOpen,
  onClose,
}: PlanetInfoModalProps) => {
  const closeButtonRef = useRef<HTMLButtonElement | null>(null);
  const modalRef = useRef<HTMLDivElement | null>(null);

  // Escapeキーで閉じる処理 & フォーカス管理 & スクロールロック
  useEffect(() => {
    if (!isOpen) return;

    // 初回フォーカスを閉じるボタンへ当てる
    const timer = setTimeout(() => {
      closeButtonRef.current?.focus();
    }, 50);

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        onClose();
        return;
      }

      // Tabキーでのフォーカストラップ
      if (e.key === 'Tab' && modalRef.current) {
        const focusableElements = modalRef.current.querySelectorAll<HTMLElement>(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (focusableElements.length === 0) return;

        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (e.shiftKey) {
          if (document.activeElement === firstElement) {
            e.preventDefault();
            lastElement.focus();
          }
        } else {
          if (document.activeElement === lastElement) {
            e.preventDefault();
            firstElement.focus();
          }
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      clearTimeout(timer);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  if (!isOpen || !planet) {
    return null;
  }

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  return (
    <div
      className="info-modal"
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
    >
      <div className="info-modal-backdrop" onClick={onClose} />
      <div className="info-card" ref={modalRef}>
        {/* モーダルヘッダー */}
        <div className="info-header">
          <div className="info-title" id="modal-title">
            <span>{planet.name}</span>
            <span className="info-subtitle">{planet.englishName}</span>
          </div>
          <button
            ref={closeButtonRef}
            type="button"
            className="close-btn"
            onClick={onClose}
            aria-label="閉じる"
          >
            ✕
          </button>
        </div>

        {/* モーダル本文 */}
        <div className="info-body">
          <div className="info-spec-grid">
            <div className="spec-item">
              <span className="spec-label">直径 (赤道)</span>
              <span className="spec-value">{planet.diameterKm}</span>
            </div>

            <div className="spec-item">
              <span className="spec-label">公転周期</span>
              <span className="spec-value">{planet.orbitPeriodDays}</span>
            </div>

            <div className="spec-item">
              <span className="spec-label">表面温度</span>
              <span className="spec-value">{planet.surfaceTemp}</span>
            </div>

            <div className="spec-item">
              <span className="spec-label">既知の衛星数</span>
              <span className="spec-value">
                {planet.moonsCount > 0 ? `${planet.moonsCount} 個` : 'なし'}
              </span>
            </div>
          </div>

          <p className="info-desc">{planet.overview}</p>
        </div>
      </div>
    </div>
  );
};

