const SOLAR_SYSTEM_DATA: PlanetData = {
  id: 'solar-system',
  name: '太陽系 全体',
  englishName: 'Solar System',
  type: 'star',
  radius: 0,
  distance: 0,
  distanceAU: '約 100,000 AU (オールトの雲)',
  orbitSpeed: 0,
  rotationSpeed: 0,
  axialTilt: 60.19, // 銀河面に対する傾斜角
  gravity: '支配天体: 太陽',
  color: '#38bdf8',
  overview: '太陽を中心とし、水星から海王星までの8つの惑星、小惑星帯、エッジワース・カイパーベルト、オールトの雲で構成される惑星系。約46億年前に巨大分子雲の重力崩壊によって誕生し、天の川銀河のオリオン腕を秒速約230kmで公転しています。',
  diameterKm: '約 2875億 km (カイパーベルト外縁)',
  orbitPeriodDays: '約 2億3000万年 (銀河系公転周期)',
  surfaceTemp: '平均 2.7 K (-270.5 ℃ / 宇宙背景放射)',
  moonsCount: 293,
  notableMoons: ['月', 'エウロパ', 'ガニメデ', 'タイタン', 'エンケラドゥス', 'トリトン'],
};

const ALL_BODIES: PlanetData[] = [SUN_DATA, ...PLANETS_DATA];

const App = () => {
  // シミュレーション設定の初期状態
  const [settings, setSettings] = useState<SimulationSettings>({
    speedMultiplier: 1.0,
    isPaused: false,
    showOrbits: true,
    focusedPlanetId: 'earth', // 初期状態で地球にフォーカス
  });

  // 惑星詳細モーダルの表示状態
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);

  // 惑星選択ハンドラー (同一天体クリック時は詳細モーダルを開く)
  const handleSelectPlanet = useCallback((id: string | null) => {
    setSettings((prev) => {
      // 既に選択されている天体が再度クリックされた場合は詳細モーダルを開く
      if (id !== null && prev.focusedPlanetId === id) {
        setIsModalOpen(true);
      }
      return {
        ...prev,
        focusedPlanetId: id,
      };
    });
  }, []);

  // 3D空間ダブルクリックでモーダルを開く
  useEffect(() => {
    const handleDoubleClick = (e: MouseEvent) => {
      // モーダル内やHUDコントロール上のクリックでなければ発火
      const target = e.target as HTMLElement;
      if (target.closest('.controls-panel') || target.closest('.top-header') || target.closest('.info-card')) {
        return;
      }
      setIsModalOpen(true);
    };

    window.addEventListener('dblclick', handleDoubleClick);
    return () => {
      window.removeEventListener('dblclick', handleDoubleClick);
    };
  }, []);

  // キーボードショートカット (Space: 再生/停止, 左右矢印: 天体切替, 数字キー: 天体ダイレクト選択, Iキー: モーダル開閉, Cキー: 俯瞰リセット)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // フォーム入力中のショートカット無効化
      const activeTag = (document.activeElement?.tagName || '').toLowerCase();
      if (activeTag === 'input' || activeTag === 'textarea' || activeTag === 'select') {
        return;
      }

      // Spaceキー: 再生 / 一時停止切替
      if (e.code === 'Space') {
        e.preventDefault();
        setSettings((prev) => ({
          ...prev,
          isPaused: !prev.isPaused,
        }));
        return;
      }

      // 'i' / 'I' キー: 詳細モーダル開閉
      if (e.key === 'i' || e.key === 'I') {
        e.preventDefault();
        setIsModalOpen((prev) => !prev);
        return;
      }

      // 'c' / 'C' キー: 全体俯瞰へリセット
      if (e.key === 'c' || e.key === 'C') {
        e.preventDefault();
        setSettings((prev) => ({
          ...prev,
          focusedPlanetId: null,
        }));
        return;
      }

      // 数字キー 0〜8: 天体ジャンプ (0: 太陽, 1: 水星, ..., 8: 海王星)
      const num = parseInt(e.key, 10);
      if (!isNaN(num) && num >= 0 && num < ALL_BODIES.length) {
        e.preventDefault();
        setSettings((prev) => ({
          ...prev,
          focusedPlanetId: ALL_BODIES[num].id,
        }));
        return;
      }

      // 左右矢印キー: 天体順送り/逆送り
      if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
        e.preventDefault();
        setSettings((prev) => {
          const currentIndex = prev.focusedPlanetId
            ? ALL_BODIES.findIndex((b) => b.id === prev.focusedPlanetId)
            : -1;

          let nextIndex = 0;
          if (e.key === 'ArrowRight') {
            nextIndex = currentIndex === -1 ? 0 : (currentIndex + 1) % ALL_BODIES.length;
          } else {
            nextIndex = currentIndex <= 0 ? ALL_BODIES.length - 1 : currentIndex - 1;
          }

          return {
            ...prev,
            focusedPlanetId: ALL_BODIES[nextIndex].id,
          };
        });
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  // 選択された天体データの取得 (未選択時は太陽系全体の概要データをフォールバック)
  const focusedPlanet =
    ALL_BODIES.find((b) => b.id === settings.focusedPlanetId) || SOLAR_SYSTEM_DATA;

  return (
    <div className="solar-app">
      {/* 3D レンダリングキャンバス */}
      <SolarSystemCanvas
        settings={settings}
        onSelectPlanet={handleSelectPlanet}
      />

      {/* HUD オーバーレイ UI */}
      <div className="hud-overlay">
        {/* 上部ヘッダー */}
        <header className="top-header">
          <h1 className="app-title">
            <span>☀️ リアルタイム3D太陽系シミュレーター</span>
          </h1>
          <p className="app-subtitle">
            ドラッグで視点回転・ホイール/ピンチでズーム・クリック/数字キーで天体選択・ダブルクリック/Iキーで解説
          </p>
        </header>

        {/* コントロール群 (惑星バー & 下部操作パネル) */}
        <ControlsBar
          settings={settings}
          onUpdateSettings={setSettings}
          onSelectPlanet={handleSelectPlanet}
          onOpenModal={() => setIsModalOpen(true)}
        />
      </div>

      {/* 惑星・太陽および太陽系全体の詳細解説モーダル */}
      <PlanetInfoModal
        planet={focusedPlanet}
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
      />
    </div>
  );
};

export default App;
